 public void PreviewOverloadScope(string folder){
  previewRun=true;Directory.CreateDirectory(folder);var cards=catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.Overload>0).ToArray();Check(cards.Length==9&&cards.All(c=>matchRules.Supports(c)),"All nine frozen Classic overload cards are supported");
  foreach(var card in cards){var sample=MatchFixture("SHAMAN");if(card.BaseId=="EX1_251"){sample.Summon(1,"VAN_CS2_182");sample.Summon(1,"VAN_CS2_182");}int id=Inject(sample,card.BaseId);string mask=sample.Rules.Target(card,null);Check(sample.Play(0,id,mask=="ANY_CHARACTER"?new MatchTarget(1):null).Success&&sample.Players[0].Overload==card.Overload&&sample.Players[0].LockedMana==0,"Played overload card queues its frozen magnitude: "+card.Name);}
  var g=MatchFixture("SHAMAN");int bolt=Inject(g,"EX1_238"),burst=Inject(g,"EX1_241");g.Play(0,bolt,new MatchTarget(1));g.Play(0,burst,new MatchTarget(1));Check(g.Players[0].Overload==3&&g.Players[0].Mana==6&&g.Players[0].LockedMana==0,"Multiple overload cards stack without locking current mana");g.EndTurn();Check(g.Players[0].Overload==3&&g.Players[1].LockedMana==0,"Overload waits through the opponent turn and does not affect opponent");g.EndTurn();Check(g.Players[0].Overload==0&&g.Players[0].LockedMana==3&&g.Players[0].Mana==7,"Next own turn consumes the queue and locks three crystals");bolt=Inject(g,"EX1_238");g.Play(0,bolt,new MatchTarget(1));Check(g.Players[0].LockedMana==3&&g.Players[0].Overload==1,"Current lock and next-turn queue remain independent");g.EndTurn();g.EndTurn();Check(g.Players[0].LockedMana==1&&g.Players[0].Mana==9&&g.Players[0].Overload==0,"New overload replaces rather than adds to expired previous lock");g.EndTurn();g.EndTurn();Check(g.Players[0].LockedMana==0&&g.Players[0].Mana==10,"Mana fully unlocks on following turn without new overload");
  g=MatchFixture("SHAMAN");g.Players[0].MaxMana=g.Players[0].Mana=2;OverloadRules.Queue(g,0,8);g.EndTurn();g.EndTurn();Check(g.Players[0].MaxMana==3&&g.Players[0].LockedMana==3&&g.Players[0].Mana==0,"Overload beyond available crystals clamps the actual locked count");g.EndTurn();g.EndTurn();Check(g.Players[0].LockedMana==0&&g.Players[0].Mana==4,"Excess queued overload does not spill into an extra turn");
  g=MatchFixture("SHAMAN");g.Players[0].LockedMana=3;g.Players[0].Mana=7;int coin=Inject(g,"GAME_COIN");g.Play(0,coin);int innervate=Inject(g,"EX1_169");g.Play(0,innervate);Check(g.Players[0].Mana==7&&g.Players[0].LockedMana==3,"Coin and Innervate cannot fill locked crystals at ten total crystals");g.Players[0].MaxMana=5;g.Players[0].LockedMana=2;g.Players[0].Mana=3;innervate=Inject(g,"EX1_169");g.Play(0,innervate);Check(g.Players[0].Mana==5&&g.Players[0].LockedMana==2&&g.Players[0].MaxMana==5,"Temporary mana may add available temporary crystals below the ten-crystal cap");Check(Enumerable.Range(0,10).Count(n=>OverloadRules.IsFilled(g.Players[0],n))==5&&!OverloadRules.IsFilled(g.Players[0],3)&&!OverloadRules.IsFilled(g.Players[0],4),"Crystal display fills temporary slots without coloring locked slots as usable");
  g=MatchFixture("SHAMAN");g.Summon(0,"VAN_EX1_243");Check(g.Players[0].Overload==0,"Summoned overload minion does not count as a played overload card");bolt=Inject(g,"EX1_238");g.Players[0].Mana=0;Check(!g.Play(0,bolt,new MatchTarget(1)).Success&&g.Players[0].Overload==0&&g.Players[0].Hand.Count==1,"Insufficient mana rejects without queuing overload");g.Players[0].Mana=10;Check(!g.Play(0,bolt).Success&&g.Players[0].Overload==0&&g.Players[0].Mana==10,"Invalid target rejects without cost or overload");
  g=MatchFixture("WARRIOR");bolt=Inject(g,"EX1_238");Check(g.Play(0,bolt,new MatchTarget(1)).Success&&g.Players[0].Overload==1,"Foreign hand spell overload applies to actual caster");
  g=MatchFixture("SHAMAN");int fork=Inject(g,"EX1_251");g.Summon(1,"VAN_CS2_182");Check(!g.Play(0,fork).Success&&g.Players[0].Mana==10&&g.Players[0].Overload==0,"Forked Lightning requires two enemy minions before spending");g.Summon(1,"VAN_CS2_182");g.Summon(1,"VAN_CS2_182");Check(g.Play(0,fork).Success&&g.Players[1].Board.Count(u=>u.DamageTaken==2)==2&&g.Players[1].Board.Count(u=>u.DamageTaken==0)==1&&g.Players[0].Overload==2,"Forked Lightning hits two distinct random minions and queues two overload");
  g=MatchFixture("SHAMAN");g.Summon(0,"VAN_EX1_563");g.Summon(1,"VAN_CS2_182");g.Summon(1,"VAN_CS2_182");fork=Inject(g,"EX1_251");g.Play(0,fork);Check(g.Players[1].Board.Count==0&&g.VisualEvents.Count(e=>e.Kind=="damage"&&e.Amount==7)==2,"Forked Lightning adds spell power separately to both hits");
