 void VerifyOverloadTcp(string folder){
  LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){previewRun=true,ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);
  try{lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="SHAMAN");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Overload fixture connects real TCP peers");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan synchronized");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Guest mulligan starts fixture");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest overload turn begins");var game=lanAuthority.Game;foreach(var p in game.Players){p.Hand.Clear();p.Board.Clear();}game.Players[1].Mana=game.Players[1].MaxMana=10;game.Summon(0,"VAN_CS2_182");game.Summon(0,"VAN_CS2_182");int fork=Inject(game,"EX1_251",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==fork),"Forked Lightning hand fixture reaches guest");guest.BeginCard(fork);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Overload==2,"Host queues guest overload and publishes it");Check(game.Players[1].Mana==9&&guest.match.Players[1].Mana==9&&game.Players[1].LockedMana==0,"Current mana pays cost but remains unlocked");Check(enemyHandStatus.Text.Contains("下回合锁2")&&OverloadRules.ResourceLabel(guest.match.Players[1],false).Contains("下回合锁2"),"Both views expose upcoming overload");guest.Opacity=1;guest.Render(Path.Combine(folder,"98-overload-pending-normal.png"));guest.Opacity=0;guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&match.Active==0,"Host turn begins while guest overload waits");DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].LockedMana==2,"Next guest turn activates two locked crystals on both peers");Check(game.Players[1].Mana==8&&guest.match.Players[1].Mana==8&&game.Players[1].Overload==0&&guest.match.Players[1].Overload==0,"Authoritative lock and available mana agree");guest.Opacity=1;guest.Render(Path.Combine(folder,"99-overload-locked-normal.png"));guest.ApplyMode(true);guest.Render(Path.Combine(folder,"100-overload-locked-minimal.png"));guest.Opacity=0;Check(guest.Width==392&&guest.Height==300,"Overload markers fit minimal office window");guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&match.Active==0,"Following host turn synchronized");DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].LockedMana==0,"Following guest turn restores locked crystals");Check(game.Players[1].Mana==10&&guest.match.Players[1].Mana==10&&game.Log.SequenceEqual(guest.match.Log),"Restored mana and public history agree across peers");
  }finally{guest.LeaveLan();guest.Close();LeaveLan();}
 }
